from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'exports/tera_v2'

def main():
    crowns=json.loads((OUT/'crown_manifest.json').read_text());surface=json.loads((OUT/'surface_verification.json').read_text());catalogue=json.loads((OUT/'catalogue_report.json').read_text());queue=json.loads((OUT/'project_queue.json').read_text())
    labels={'fire':'Feu','water':'Eau','normal':'Normal','flying':'Vol','grass':'Plante','fighting':'Combat','poison':'Poison','ground':'Sol','rock':'Roche','bug':'Insecte','steel':'Acier','electric':'Électrik','psychic':'Psy','ice':'Glace','dragon':'Dragon','dark':'Ténèbres','fairy':'Fée','ghost':'Spectre','stellar':'Stellaire'}
    html='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Couronnes et verre prismatique</title><style>*{box-sizing:border-box}body{margin:0;background:#101925;color:#edf5fa;font:16px system-ui}main{max-width:1160px;margin:auto;padding:36px 24px}h1{font-size:clamp(32px,5vw,54px);line-height:1.1;margin:16px 0}h2{margin-top:0;font-size:27px}p{line-height:1.7;color:#b6c7d9}.eyebrow{letter-spacing:2px;color:#a5e0d7;font-size:12px}.stats{display:flex;gap:12px;flex-wrap:wrap;margin:24px 0}.stats div{flex:1;min-width:200px;border:1px solid #334359;border-radius:12px;padding:20px}.stats b{display:block;font-size:30px;color:#abe8dc}.stats small{display:block;color:#aabfd2;margin-top:8px}section{margin:24px 0;padding:28px;border:1px solid #334359;border-radius:16px;background:#152030}img{image-rendering:pixelated;max-width:100%}.wide{display:block;width:100%;height:auto}.note{border-left:3px solid #e3b878;padding:12px 18px;background:#202c3c;color:#d7bd99;line-height:1.65}.toolbar{display:flex;gap:14px;align-items:center;flex-wrap:wrap;margin:20px 0}select,button{background:#22334a;color:#edf5fa;border:1px solid #4a627c;border-radius:7px;padding:10px 14px;font:inherit}.model{display:flex;gap:16px;align-items:center;flex-wrap:wrap;min-height:230px;background:#101925;border-radius:10px;padding:16px}.model figure{margin:0;text-align:center}.model img{width:128px;height:160px;object-fit:contain}.model figcaption{color:#aabfd2;font-size:13px}.portraits{display:grid;grid-template-columns:repeat(auto-fit,minmax(118px,1fr));gap:12px}.portrait{text-align:center;border:1px solid #34455b;padding:12px;border-radius:10px}.portrait img{width:80px;height:80px}.portrait small{display:block;color:#dcbb83;font-size:11px}.portrait p{font-size:12px;margin:8px 0}.queue{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.queue article{padding:16px;background:#101925;border-radius:10px}.queue img{width:80px}.queue h3{font-size:17px}.queue p{font-size:13px}a{color:#a5e0d7}footer{padding:12px;color:#9bb1c4;font-size:13px}@media(max-width:750px){.queue{grid-template-columns:1fr 1fr}section{padding:16px}}</style><main><div class="eyebrow">ATELIER TÉRACRISTAL · LOT 02</div><h1>Couronnes &<br>verre prismatique.</h1><p>Les accessoires sont régénérés séparément du Pokémon. Le nouveau traitement de surface suit chaque silhouette native : facettes, réfraction locale, reflets blancs et dispersion colorée animés, sans modifier l’alpha ni la durée des actions.</p>'''
    html+=f'''<div class="stats"><div><b>19 types</b><small>Modèles dessinés · non tous validés ni multidirectionnels</small></div><div><b>{surface['native_sheet_count']} planches locales</b><small>{surface['exported_phase_sheets']} variantes · 24 phases de lumière</small></div><div><b>{catalogue['animation_sheet_count']:,}</b><small>Planches SpriteCollab indexées · 12 testées à distance</small></div></div>'''
    html+='''<section><h2>01 / Les modèles de couronne</h2><p>Feu : quatre vues cardinales. Eau : huit propositions d’angle. Les 17 autres types : une vue frontale chacun. Les bandes pendantes de la première génération Eau/Normal/Plante ont été reprises au générateur.</p><img class="wide" src="exports/tera_v2/review/all_crown_models.png" alt="Planche des 19 modèles de couronne"><div class="toolbar"><label for="type">Examiner un modèle</label><select id="type"></select></div><div class="model" id="models"></div><p class="note">Ce ne sont pas 19 couronnes finalisées pour tous les sprites. Pas de tête ni de corps de Pokémon porteur dans ces accessoires ; les joyaux frontaux n’ont pas d’yeux. Les emblèmes propres aux types (crâne Poison, œil Psy, masque Ténèbres, fantôme Spectre) restent décoratifs. Le modèle Stellaire est refusé pour utilisation : statue non fidèle et nombre exact des ornements à reprendre. Le nombre de ballons Vol et les vues Eau doivent aussi être corrigés/vérifiés. Les nouveaux modèles n’écrasent pas les anciens réglages d’attache.</p></section><section><h2>02 / Une surface, pas une aura</h2><p>Nouveau modèle Feu et reflets réunis sur quatre formes locales, dans les quatre vues cardinales. Première pose Idle, largeur et assise de tête individualisées ; occultations cornes/oreilles encore provisoires.</p><img class="wide" src="exports/tera_v2/review/fire_attached_glass.gif" alt="Couronne Feu régénérée et matière de verre sur quatre formes"><p>Comparaison sur douze silhouettes natives très différentes. À gauche : l’original. À droite : les reflets animés sur la même pose. Les planches complètes ont été traitées et vérifiées, pas seulement ces découpes de présentation.</p><img class="wide" src="exports/tera_v2/review/catalogue_glass_sample.gif" alt="Comparaison animée de douze sprites natifs et de leur surface cristalline"><div class="toolbar"><label for="surface">Actions natives + lumière indépendante</label><select id="surface"><option value="charizard">Dracaufeu · original / verre</option><option value="tirtouga_v5">Carapagos · original / verre</option><option value="gigantamax_charizard">Gigamax · verre, huit directions</option></select></div><img class="wide" id="surface-preview" src="exports/tera_v2/review/charizard_glass_eight.gif" alt="Reflets dans les huit directions"><p class="note">Le moteur de traitement ne contient pas de liste d’espèces : il accepte toute planche native répertoriée, à la demande. Cela ne signifie pas que les 55 953 planches ont toutes été calculées, ni que le shader est installé dans PMDO. Les tests réalisés portent sur six dossiers locaux et douze planches distantes. Intégration et rendu réel Ground/Dungeon toujours non testés.</p><p><a href="exports/tera_v2/README.md">Guide et commande pour traiter une autre planche</a> · <a href="exports/tera_v2/catalogue_report.json">Couverture exacte</a> · <a href="exports/tera_v2/surface_verification.json">Contrôles locaux</a></p></section><section><h2>03 / Carapagos — revue regroupée</h2><p>Les 32 actions et 16 portraits déjà exportés sont réunis ici. Ce regroupement n’est pas compté comme une nouvelle production artistique. Les six originaux conservés sont inchangés ; les autres portraits et les sprites attendent encore leur validation artistique.</p><div class="toolbar"><label for="action">Animation</label><select id="action">'''
    actions=sorted((ROOT/'exports/pokemon_custom/tirtouga_v5/review/gifs').glob('*.gif'))
    for p in actions:html+=f'<option value="{p.stem}"'+(' selected' if p.stem=='Idle' else '')+f'>{p.stem}</option>'
    html+='''</select></div><img class="wide" id="action-preview" src="exports/pokemon_custom/tirtouga_v5/review/gifs/Idle.gif" alt="Animation Carapagos V5"><div class="portraits">'''
    preserved=queue['carapagos']['approved_original_hashes_preserved']
    for p in sorted((ROOT/'exports/pokemon_custom/tirtouga_portraits_v4/portraits_individual').glob('*.png')):
        status='Original conservé' if p.name in preserved else 'À valider'
        html+=f'<div class="portrait"><img src="{p.relative_to(ROOT)}" alt="{p.stem}"><p>{p.stem}</p><small>{status}</small></div>'
    html+='''</div></section><section><h2>04 / Ressources manquantes du projet</h2><p>Périmètre confirmé : la file du projet, pas la création de tous les absents de SpriteCollab. Les dix générations ont été utilisées pour les couronnes. Les tentatives suivantes Zarude et Terapagos Stellaire ont été bloquées par la limite : aucun nouveau sprite n’est annoncé pour eux.</p><div class="queue">'''
    for item,folder in zip(queue['priority'],['zarude','terapagos_stellar','mega_raichu_x','mega_raichu_y']):
        html+=f'''<article><img src="source/pokemon_custom/next_species/references/{folder}/Normal.png" alt="Portrait natif existant"><h3>{item['name']}</h3><p>Portrait Normal existant, à conserver.<br>{len(item['missing_required_portraits'])} émotions requises manquantes.<br>Sprites : à produire / corriger.</p></article>'''
    html+='''</div><p>Les formes Méga-Raichu X/Y ont été retrouvées dans les slots 0026/0002 et 0026/0003 : leurs portraits Normal existent déjà. L’audit du projet recense aussi 46 espèces de base sans sprites ; elles conservent leurs portraits existants.</p><p><a href="exports/tera_v2/project_queue.json">File détaillée : existants et manquants</a></p></section><footer>Références de design : descriptions des Tera Jewels de Scarlet/Violet ; modèles générés, pas copies certifiées canoniques. Personnages natifs : SpriteCollab, révision 3609a86 ; crédits conservés. Aucun portrait existant n’a été remplacé.</footer></main><script>'''
    html+='const MODELS='+json.dumps(crowns['records'])+';const LABELS='+json.dumps(labels,ensure_ascii=False)+';'
    html+='''const type=document.getElementById('type');for(const [key,label] of Object.entries(LABELS)){const o=document.createElement('option');o.value=key;o.textContent=label;type.appendChild(o)}function show(){const host=document.getElementById('models');host.replaceChildren();for(const r of MODELS.filter(r=>r.type===type.value)){const f=document.createElement('figure'),im=document.createElement('img'),c=document.createElement('figcaption');im.src='exports/tera_v2/'+r.file;im.alt=LABELS[r.type];c.textContent=['D','DR','R','UR','U','UL','L','DL'][r.requested_direction]+' · proposition';f.append(im,c);host.appendChild(f)}}type.onchange=show;show();document.getElementById('surface').onchange=e=>document.getElementById('surface-preview').src='exports/tera_v2/review/'+e.target.value+'_glass_eight.gif';document.getElementById('action').onchange=e=>document.getElementById('action-preview').src='exports/pokemon_custom/tirtouga_v5/review/gifs/'+e.target.value+'.gif';</script></html>'''
    (ROOT/'apercu_tera_v2.html').write_text(html)

if __name__=='__main__':main()
